// A fast, collision-resistant pure JS hash function (alternative to SHA-256)
function generateHash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

// Remove duplicates customized:
// 1. Standardizes target data (e.g., stripping spaces, forcing lowercase) so variations like " John Doe " and "john.doe" resolve to the exact same text string
// 2. Creates a hash (id) with the combination of two target data, in this case title and company
// 3. Preserve unique ids

// Import crypto for hashing (built-in in modern Node.js environments)
// const crypto = require('crypto'); // not alowed in n8n

// 1. Extract the jobs array from your input structure
const jobs = $input.all().map(item => item.json);
const uniqueItems = new Map();

console.log(`[DEDUPLICATION START] Processing ${jobs.length} total jobs.`); // Check total length

for (let index = 0; index < jobs.length; index++) {
  const item = jobs[index];
  // 2. Normalize custom fields (title and company): the "core identity"
  const normalizedTitle = (item.title || '').trim().toLowerCase().replace(/\s+/g, '');
  const normalizedCompany = (item.company || '').trim().toLowerCase().replace(/\s+/g, '');

  // 3. Combine into a unique identity string
  const coreIdentityString = `${normalizedTitle}|${normalizedCompany}`;

  // 4. Generate a deterministic SHA-256 hash to use as _id
  const hashId = generateHash(coreIdentityString);

  // Pad or truncate to exactly 24 hex chars for MongoDB ObjectId compatibility
  const mongoId = hashId.padStart(24, '0').slice(-24);

  // 5. Build your customized output object structure
  const formattedItem = {
    json: {
      jobhash: mongoId, // Injected hash ID
      title: item.title,
      company: item.company,
      location: item.location,
      url: item.url,
      source_id: item.id,
      description: item.description,
      source: item.source
    }
  };

  // 6. De-duplicate: Keep only the first occurrence of this specific hash
  if (!uniqueItems.has(hashId)) {
    console.log(`:) [Item ${index}] Keeping unique job: "${item.title}" by ${item.company} (jobhash: ${hashId})`);
    uniqueItems.set(hashId, formattedItem);
  } else {
    console.warn(`:( [Item ${index}] Dropping duplicate job: "${item.title}" by ${item.company}`);
  }
}

// Return only the unique items
console.log(`[DEDUPLICATION END] Returning ${uniqueItems.size} unique jobs.`);
return Array.from(uniqueItems.values());

