return $input.all().map(item => {
  const html = item.json.solution?.response || "";

  // Extract the JSON string between <pre> and </pre>
  const match = html.match(/<pre>([\s\S]*?)<\/pre>/);

  if (!match) {
    return { json: { error: "No <pre> block found", raw: html.slice(0, 200) } };
  }

  // Decode HTML entities that FlareSolverr escaped
  let jsonText = match[1]
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;/g, "'");

  try {
    const parsed = JSON.parse(jsonText);
    return { json: parsed };
  } catch (e) {
    return { json: { error: e.message, snippet: jsonText.slice(0, 300) } };
  }
});

